-- ============================================
-- MIGRACION SQLite -> PostgreSQL (Supabase)
-- Proyecto: GO VISTA Sales Tracker
-- Fecha: 2026-08-25
-- ============================================

DROP TABLE IF EXISTS core_outflow CASCADE;
DROP TABLE IF EXISTS core_cashcount CASCADE;
DROP TABLE IF EXISTS core_sale CASCADE;
DROP TABLE IF EXISTS core_backup CASCADE;
DROP TABLE IF EXISTS core_customer CASCADE;
DROP TABLE IF EXISTS core_plan CASCADE;
DROP TABLE IF EXISTS core_user CASCADE;
DROP TABLE IF EXISTS django_session CASCADE;
DROP TABLE IF EXISTS django_admin_log CASCADE;
DROP TABLE IF EXISTS auth_group_permissions CASCADE;
DROP TABLE IF EXISTS auth_group CASCADE;
DROP TABLE IF EXISTS auth_permission CASCADE;
DROP TABLE IF EXISTS django_content_type CASCADE;
DROP TABLE IF EXISTS django_migrations CASCADE;

CREATE TABLE django_migrations (id bigserial PRIMARY KEY, app varchar(255) NOT NULL, name varchar(255) NOT NULL, applied timestamp with time zone NOT NULL);
CREATE TABLE django_content_type (id bigserial PRIMARY KEY, app_label varchar(100) NOT NULL, model varchar(100) NOT NULL, UNIQUE(app_label, model));
CREATE TABLE auth_group (id bigserial PRIMARY KEY, name varchar(150) NOT NULL UNIQUE);
CREATE TABLE auth_permission (id bigserial PRIMARY KEY, content_type_id bigint NOT NULL REFERENCES django_content_type(id), codename varchar(100) NOT NULL, name varchar(255) NOT NULL);
CREATE TABLE auth_group_permissions (id bigserial PRIMARY KEY, group_id bigint NOT NULL REFERENCES auth_group(id), permission_id bigint NOT NULL REFERENCES auth_permission(id), UNIQUE(group_id, permission_id));
CREATE TABLE django_session (session_key varchar(40) PRIMARY KEY, session_data text NOT NULL, expire_date timestamp with time zone NOT NULL);
CREATE TABLE django_admin_log (id bigserial PRIMARY KEY, action_time timestamp with time zone NOT NULL, object_id text, object_repr varchar(200) NOT NULL, action_flag smallint NOT NULL, change_message text NOT NULL, content_type_id bigint REFERENCES django_content_type(id), user_id bigint NOT NULL);

CREATE TABLE core_user (id bigserial PRIMARY KEY, name varchar(120) NOT NULL, password varchar(255) NOT NULL, role varchar(10) NOT NULL DEFAULT 'ventas', active boolean NOT NULL DEFAULT true);
CREATE TABLE core_plan (id bigserial PRIMARY KEY, code varchar(30) NOT NULL UNIQUE, label varchar(120) NOT NULL, type varchar(10) NOT NULL, speed integer, monthly numeric(12,2) NOT NULL, installation numeric(12,2) NOT NULL, active boolean NOT NULL DEFAULT true, legacy boolean NOT NULL DEFAULT false);
CREATE TABLE core_customer (id bigserial PRIMARY KEY, code varchar(40) NOT NULL UNIQUE, name varchar(160) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE core_sale (id bigserial PRIMARY KEY, date date NOT NULL, clientCode varchar(40) NOT NULL, clientName varchar(160) NOT NULL, total numeric(12,2) NOT NULL, lastEditedAt timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), plan_id bigint NOT NULL REFERENCES core_plan(id), createdBy_id bigint NOT NULL REFERENCES core_user(id), lastEditedBy_id bigint REFERENCES core_user(id), changeReason varchar(120) NOT NULL DEFAULT '', notes varchar(255) NOT NULL DEFAULT '', planFrom varchar(60) NOT NULL DEFAULT '', requestType varchar(20) NOT NULL DEFAULT 'nuevo_contrato', totalFrom numeric(12,2), customer_id bigint REFERENCES core_customer(id), serviceType varchar(20) NOT NULL);
CREATE INDEX idx_sale_date ON core_sale(date);
CREATE INDEX idx_sale_request ON core_sale(requestType);
CREATE INDEX idx_sale_service ON core_sale(serviceType);
CREATE TABLE core_cashcount (id bigserial PRIMARY KEY, date date NOT NULL, coin_050 integer NOT NULL DEFAULT 0, coin_1 integer NOT NULL DEFAULT 0, coin_2 integer NOT NULL DEFAULT 0, coin_5 integer NOT NULL DEFAULT 0, bill_10 integer NOT NULL DEFAULT 0, bill_20 integer NOT NULL DEFAULT 0, bill_50 integer NOT NULL DEFAULT 0, bill_100 integer NOT NULL DEFAULT 0, bill_200 integer NOT NULL DEFAULT 0, updated_at timestamp with time zone NOT NULL DEFAULT now(), createdBy_id bigint REFERENCES core_user(id), UNIQUE(date, createdBy_id));
CREATE TABLE core_outflow (id bigserial PRIMARY KEY, date date NOT NULL, personName varchar(160) NOT NULL, amount numeric(12,2) NOT NULL, concept varchar(255) NOT NULL DEFAULT '', createdBy_id bigint REFERENCES core_user(id), created_at timestamp with time zone DEFAULT now());
CREATE TABLE core_backup (id bigserial PRIMARY KEY, filename varchar(255) NOT NULL, backup_type varchar(10) NOT NULL, status varchar(10) NOT NULL DEFAULT 'success', created_at timestamp with time zone NOT NULL DEFAULT now(), size bigint NOT NULL DEFAULT 0, storage_path varchar(500) NOT NULL DEFAULT '', checksum varchar(64) NOT NULL DEFAULT '', created_by_id bigint REFERENCES core_user(id));

SELECT setval('django_content_type_id_seq', (SELECT COALESCE(MAX(id),1) FROM django_content_type));

SELECT setval('auth_permission_id_seq', (SELECT COALESCE(MAX(id),1) FROM auth_permission));

SELECT setval('django_migrations_id_seq', (SELECT COALESCE(MAX(id),1) FROM django_migrations));

SELECT setval('core_user_id_seq', (SELECT COALESCE(MAX(id),1) FROM core_user));

SELECT setval('core_plan_id_seq', (SELECT COALESCE(MAX(id),1) FROM core_plan));

SELECT setval('core_backup_id_seq', (SELECT COALESCE(MAX(id),1) FROM core_backup));

-- FIN DE MIGRACION